function fzSource(id){const s=FZ_SOURCES.find(x=>x.id===id);return `<p class="source">${external(s.url,s.name+' · '+s.title)} · ${s.date}</p>`;}
function fzEntry(){return `<aside class="fz-entry"><div><span class="eyebrow">AKTUELLER BEZUG · 30. SEPTEMBER 2026</span><h2>Wenn Rettung noch möglich ist.</h2><p>Fallakte Flydubai: Texte und Filme prüfen – und die Annahmen in «Terror» hinterfragen.</p></div><a class="button secondary" href="#flydubai">Fallakte öffnen →</a></aside>`;}
function fzRail(id){return `<nav class="fz-rail" aria-label="Stationen der Fallakte">${FZ_STATIONS.map((s,i)=>`<a href="#flydubai/${s.id}" ${s.id===id?'aria-current="page"':''}><span>0${i+1}</span>${s.title}</a>`).join('')}</nav>`;}
function flydubai(id){
 const unit=FZ_STATIONS.find(s=>s.id===id);
 if(id&&!unit)return missing();
 const intro=`<p class="breadcrumb"><a href="#lektuere">Text & Szenenfilm</a> / <a href="#flydubai">Fallakte Flydubai</a></p>`;
 if(!unit)return intro+head('REALER FALL / FZ1073','Wenn Rettung<br>noch möglich ist.','Ein gewaltsamer Zwischenfall im Cockpit. Eine sichere Landung. Und die Frage, was Menschen in einer Extremsituation tatsächlich wissen können.')+`<div class="workspace-grid"><section class="case-panel fz-case"><span class="eyebrow">FALLAKTE · 30. SEPTEMBER 2026</span><h2>Dubai → Tel Aviv<br>Landung in Tabuk</h2><p>Flydubai bestätigt eine Auseinandersetzung im Cockpit und eine sichere Landung. Wie der Angriff genau ablief und was ihn motivierte, ist Gegenstand der Untersuchung.</p><p class="fz-stamp">ZEIT-ERGÄNZUNG 02.10.2026 · KEIN LIVE-TICKER</p><a class="button accent" href="#flydubai/ereignis">Die Akte öffnen →</a></section><section class="card"><span class="eyebrow">DEINE LEITFRAGE</span><h2>Wann halten wir eine Lage für ausweglos?</h2><p>Prüfe zuerst die Meldungen. Vergleiche dann mit «Terror»: Welche Handlungsmöglichkeiten werden den Menschen an Bord zugestanden?</p><p>Der reale Fall ist kein Beweis für die Schuld oder Unschuld der literarischen Figur Lars Koch. Er hilft, die Voraussetzungen ihrer Argumente zu untersuchen.</p><a href="#flydubai/transfer">Direkt zum Vergleich mit dem Stück →</a></section></div><section class="section"><div class="section-head"><h2>Fünf Zugänge zur Fallakte</h2><span class="muted">Einzeln oder nacheinander bearbeiten</span></div><div class="grid">${FZ_STATIONS.map((s,i)=>linkCard('flydubai/'+s.id,'0'+(i+1),s.title,s.text,s.meta)).join('')}</div></section><p class="source">Eigene Zusammenfassungen und Lernaufträge. Die ZEIT-Analyse ist in eigenen Worten in die Fallakte integriert; Originaltexte und Filme sind ergänzend verlinkt. Die Nachrichtenseiten können nach diesem Quellenstand aktualisiert werden. ${external(FZ_SOURCES.find(s=>s.id==='airline').url,'Offizielle Mitteilungen')}</p>`;
 const body={ereignis:fzEvent,quellen:fzTexts,filme:fzFilms,zeit:fzZeit,transfer:fzTransfer}[id]();
 const n=FZ_STATIONS.indexOf(unit),next=FZ_STATIONS[n+1];
 return intro+head('FALLAKTE FLYDUBAI / 0'+(n+1),unit.title,unit.text)+fzRail(id)+`<div class="fz-content">${body}</div><div class="reader-next"><a class="button secondary" href="#${n?'flydubai/'+FZ_STATIONS[n-1].id:'flydubai'}">← ${n?'Vorige Station':'Übersicht'}</a><a class="button" href="#${next?'flydubai/'+next.id:'journal'}">${next?'Weiter: '+next.title:'Zum Arbeitsjournal'} →</a></div>`;
}
function fzEvent(){return `<section class="card"><span class="eyebrow">BASISTEXT · EIGENE ZUSAMMENFASSUNG</span><h2>Ein Ereignis, verschiedene Wissensstände</h2><p>Am 30. September 2026 sollte Flug FZ1073 von Dubai nach Tel Aviv fliegen. Nach einer Auseinandersetzung im Cockpit wurde die Maschine nach Tabuk in Saudi-Arabien umgeleitet. Die Fluggesellschaft erklärte, mitreisende diensthabende Crewmitglieder hätten das Flugzeug gesichert und gelandet. Eine weitere Mitteilung kündigte die vorläufige Aussetzung der Israel-Verbindungen während der Untersuchung an.</p>${fzSource('airline')}<p>Nach israelischen Angaben soll der Co-Pilot den Kapitän verletzt und versucht haben, das Flugzeug zum Absturz zu bringen. Reuters berichtet über Aussagen von Reisenden zum Höhenverlust und zum Eingreifen von Passagieren und Besatzung sowie über verifizierte Aufnahmen aus der Kabine.</p>${fzSource('reuters')}<p>Was eine Aufnahme zeigt und was eine Erklärung dazu behauptet, sind unterschiedliche Dinge. Ein sichtbarer Verletzter belegt nicht für sich allein die Absicht eines Angreifers. Auch die Begriffe «Auseinandersetzung», «Entführungsversuch» und «Terroranschlag» enthalten unterschiedlich weitgehende Aussagen über Tat und Motiv.</p><div class="callout"><b>Gesichert, zugeschrieben, offen:</b> Halte die Quelle an der Aussage fest. Eine offizielle Behauptung ist noch kein abgeschlossenes Untersuchungsergebnis.</div></section><section class="section grid"><article class="card"><span class="eyebrow">BESTÄTIGUNG DER FLUGGESELLSCHAFT</span><h3>Landung und Sicherung</h3><p>Flydubai bestätigt die sichere Landung in Tabuk und die Sicherung durch Crewmitglieder.</p></article><article class="card"><span class="eyebrow">VORLÄUFIGE DARSTELLUNG</span><h3>Angriff und Absicht</h3><p>Die Angaben zu einem gezielten Absturzversuch müssen als israelische Darstellung gekennzeichnet bleiben. Motiv und genauer Ablauf sind noch zu untersuchen.</p></article></section><section class="section card"><h2>Ergänzung aus der ZEIT-Analyse</h2><p>Hentschke beschreibt eine Rettung durch mehrere Beteiligte: Der verletzte Kapitän habe die Tür geöffnet, Passagiere hätten den Co-Piloten überwältigt, zwei mitreisende Piloten hätten die Maschine übernommen. Der Artikel gibt dabei Medienberichte und Aussagen von Reisenden wieder; diese Rekonstruktion ist als solche zu kennzeichnen.</p><p>Daneben untersucht der Text, wie aus dem Ereignis eine Geschichte über Heldentum, Bedrohung und politische Glaubwürdigkeit wird.</p>${fzZeitRef('2–4')}<p><a href="#flydubai/zeit">Rettung, Deutung und Politik direkt in der Fallakte lesen →</a></p><h2>Deine erste Meldung</h2><p>Schreibe höchstens 80 Wörter. Nenne das bestätigte Ereignis, eine zugeschriebene Aussage und eine offene Frage.</p>${note('flydubai-meldung','Flydubai · Meldung mit Quellenstatus','Formulierungshilfen: Die Fluggesellschaft bestätigt … / Nach Angaben von … / Ungeklärt bleibt …')}${details('Hilfe · Quellenstatus präzisieren','<p>«Flydubai bestätigt die Landung» ist genauer als «Man weiss alles über den Vorfall». «Israelische Stellen sprechen von einem Absturzversuch» benennt die Urheber einer Aussage und macht ihre Vorläufigkeit sichtbar.</p>')}${rubric('flydubai-meldung')}</section>`;}
function fzTexts(){return `<div class="callout"><b>Vier Texte, unterschiedliche Funktionen.</b> Lest arbeitsteilig oder nacheinander. Vergleicht nicht nur die Aussagen, sondern auch ihre Herkunft. Mehrere Medien können dieselbe ursprüngliche Quelle verwenden.</div><div class="fz-sources">${FZ_SOURCES.map((s,i)=>`<article class="card"><span class="eyebrow">TEXT 0${i+1} · ${s.lang}</span><h2>${escape(s.name)} · ${escape(s.title)}</h2><p class="source">${escape(s.date)} · ${escape(s.type)}</p><p>${escape(s.description)}</p>${s.id==='zeit'?'<p><a class="button secondary" href="#flydubai/zeit">Integrierte ZEIT-Lektüre öffnen →</a></p>':''}<p>${external(s.url,'Originaltext öffnen')}</p><div class="callout"><b>Dein Leseauftrag</b><p>${escape(s.task)}</p></div>${note('flydubai-quelle-'+s.id,'Flydubai · Quellenprotokoll '+s.name,'Aussage → ursprüngliche Quelle → Belegstelle → Gewissheitsgrad → offene Frage')}</article>`).join('')}</div><section class="section card"><h2>Der Weg einer Behauptung</h2><p>Wähle eine konkrete Aussage. Geht sie auf eine Beobachtung, eine Unternehmensmitteilung oder eine politische Stellungnahme zurück? Wie oft wird sie lediglich weitergegeben?</p>${note('flydubai-quellenvergleich','Flydubai · Unabhängigkeit der Quellen','Behauptung · ursprünglicher Urheber · berichtende Medien · unabhängige Bestätigung oder Wiederholung')}${details('Vergleichshorizont · Erst nach der eigenen Antwort öffnen','<p>Eine Unternehmensmitteilung ist eine Primärquelle für das, was das Unternehmen erklärt; sie ist keine neutrale Gesamtrekonstruktion. Ein Augenzeuge kann seinen Standort und seine Wahrnehmung beschreiben, ohne das Motiv des Angreifers zu kennen. Drei Artikel, die dieselbe Aussage übernehmen, ergeben nicht drei unabhängige Bestätigungen.</p>')}${rubric('flydubai-quellen')}</section>`;}
function fzFilms(){return `<p class="notice">Beide Beiträge: 30. September 2026 · Englisch. Die Filme öffnen auf DW. Titel, Laufzeiten und Beschreibungen sind geprüft; eine vollständige Sichtung liegt dieser Ressource nicht zugrunde. Kabinenaufnahmen können verletzte Menschen zeigen.</p><div class="grid">${FZ_FILMS.map((f,i)=>`<article class="film-window fz-film"><div class="fz-film-slate"><span class="eyebrow">NACHRICHTENFILM 0${i+1} · DW</span><strong>${f.time}</strong><span>${f.focus}</span><a class="button accent" href="${f.url}" target="_blank" rel="noopener noreferrer">Film bei DW ansehen ↗</a></div><div><span class="eyebrow">${f.by}</span><h2>${f.title}</h2><p>${f.description}</p><h3>Dein Sichtungsauftrag</h3><p>${f.task}</p>${note('flydubai-film-'+f.id,'Flydubai · Filmprotokoll '+(i+1),'Zeitmarke · sichtbare Beobachtung · gesprochene Aussage · Quelle · Wirkung')}</div></article>`).join('')}</div><section class="section card"><h2>Sehen ist noch nicht wissen.</h2><p>Vergleiche die beiden Titel und eine konkrete Passage aus jedem Film. Wann wird berichtet, wann gedeutet? Welche Wirkung haben Wortwahl, Bildauswahl und die Reihenfolge der Aussagen?</p>${note('flydubai-filmvergleich','Flydubai · Vergleich der Nachrichtenfilme','Beobachtung mit Zeitmarke → journalistisches Mittel → Wirkung → Grenze der Aussage')}${details('Hilfe · Bild und Kommentar trennen','<p>Notiere zuerst nur das Sichtbare. Notiere daneben, was der Kommentar hinzufügt. Prüfe dann, ob das Bild genau diese zusätzliche Behauptung belegt. Ein authentisches Video kann einen Ausschnitt zuverlässig zeigen und trotzdem wesentliche Vorgeschichte auslassen.</p>')}${rubric('flydubai-filme')}</section>`;}
function fzTransfer(){return `<section class="case-panel fz-case"><span class="eyebrow">REALITÄT × DRAMA · VERGLEICH, KEINE GLEICHSETZUNG</span><h2>Wer erklärt die Menschen<br>an Bord für verloren?</h2><p>Eine von innen gelungene Rettung macht eine Frage an «Terror» besonders dringlich: Welche Möglichkeiten bleiben ausserhalb des Blickfelds der Entscheidenden?</p></section><section class="section grid"><article class="card"><span class="eyebrow">TEXTSPUR 01 · PDF 65–73</span><h2>Meisers Aussage</h2><p>Suche die Stelle, an der die Nachricht ihres Mannes und die Handlungsmöglichkeiten der Passagiere zur Sprache kommen. Was berichtet Meiser? Wann wird diese Information wem bekannt?</p><a href="#lektuere/meiser">Text und Filmszene öffnen →</a></article><article class="card"><span class="eyebrow">TEXTSPUR 02 · PDF 43–64</span><h2>Kochs Entscheidung</h2><p>Prüfe, welches Wissen Koch für seine Entscheidung beansprucht. Welche Informationen hatte er zu diesem Zeitpunkt? Welche Sicherheit entsteht erst in seiner späteren Darstellung?</p><a href="#lektuere/koch">Kochs Aussage öffnen →</a> · <a href="#lektuere/grenzfaelle">Die Grenzfälle prüfen →</a></article></section><section class="section card"><h2>Drei Unterschiede festhalten</h2><div class="grid three"><div><span class="number">01 · AUSGANG</span><p>Was ist im realen Fall tatsächlich geschehen, was wird im Drama als bevorstehende Katastrophe angenommen?</p></div><div><span class="number">02 · WISSEN</span><p>Wer weiss etwas während des Ereignisses? Wer erfährt es erst im Nachhinein?</p></div><div><span class="number">03 · SCHLUSSFOLGERUNG</span><p>Was zeigt eine erfolgreiche Rettung über Möglichkeiten – und was beweist sie nicht über einen anderen Fall?</p></div></div>${note('flydubai-vergleich','Flydubai × Terror · Vergleich','Je ein belegter Unterschied zu Ausgang, Wissen und Schlussfolgerung. Trenne Nachricht, Dramentext und eigene Deutung.')}${details('Vergleichshorizont · Eine mögliche Argumentation','<p>Der Fall stellt die vorschnelle Annahme infrage, Menschen an Bord seien handlungsunfähig. Er beweist aber nicht, dass eine Rettung in jeder Lage wahrscheinlich oder vorhersehbar wäre. Ein später bekanntes Ergebnis kann nicht ohne Weiteres zum damaligen Wissen einer entscheidenden Person gerechnet werden. Die rechtliche Bewertung verlangt zusätzlich eine eigene Prüfung; der reale Vorfall entscheidet den literarischen Prozess nicht.</p>')}</section><section class="section card"><h2>Die politische Erzählung mitprüfen</h2><p>Die integrierte ZEIT-Analyse zeigt, wie ein Rettungsereignis durch den 9/11-Vergleich und öffentliche Auftritte politische Bedeutung erhält. Vergleiche dies mit der Frage, wie Koch im Drama als Retter oder als Täter erscheint. Trenne dabei Inszenierung, Tatsachenbehauptung und rechtliche Bewertung.</p><p><a href="#flydubai/zeit">Zur integrierten ZEIT-Analyse →</a></p><h2>Dein begründeter Kommentar</h2><p><b>«Wie sicher muss eine Katastrophe sein, bevor wir sie für unausweichlich halten?»</b></p><p>Schreibe 250–350 Wörter. Verwende zwei belegte Beobachtungen aus der Fallakte und einen präzisen Textbezug. Prüfe einen Einwand und benenne die Grenze des Vergleichs.</p>${note('flydubai-kommentar','Flydubai × Terror · Kommentar','These · Nachrichtenbeleg · Textbeleg mit PDF-Seite · Gegenargument · Grenze · Schluss')}${rubric('flydubai-transfer')}<p><a href="#lektuere/nelson">Nelsons Plädoyer</a> · <a href="#lektuere/biegler">Bieglers Plädoyer</a> · <a href="#aviatik/zeit">Zeit und Wissen</a></p></section>`;}

function fzZeitRef(pages){return `<p class="source">Grundlage: Steffi Hentschke, DIE ZEIT, Analyse vom 1. Oktober 2026, 18:58 Uhr · bereitgestellte Druck-PDF, S. ${pages}. Eigene Zusammenfassung und didaktische Einordnung; keine unabhängige Bestätigung der berichteten Einzelheiten.</p>`;}
function fzZeit(){return `<section class="card"><span class="eyebrow">INTEGRIERTE LEKTÜRE · ZEIT-ANALYSE</span><h2>Aus einer Rettung wird eine politische Geschichte</h2><p>Steffi Hentschke berichtet aus Tel Aviv über den Empfang der geretteten Reisenden und fragt, welche politische Bedeutung der Vorfall erhält. Ihr Text ist eine <b>Analyse</b>: Er verbindet berichtete Ereignisse, Aussagen anderer Quellen, eigene Beobachtungen und Schlussfolgerungen. Diese Ebenen müssen wir auseinanderhalten.</p><p>Die folgenden Abschnitte erschliessen den Inhalt direkt hier. Die Seitenangaben beziehen sich auf die fünfseitige ZEIT-PDF, nicht auf die 103-seitige Ausgabe von «Terror».</p>${fzZeitRef('1–5')}</section>
<section class="section card"><span class="eyebrow">01 · HANDELN AN BORD</span><h2>Rettung ist eine Kette von Handlungen</h2><p>Nach der im Artikel wiedergegebenen Darstellung wurde der Kapitän angegriffen und schwer verletzt. Er habe noch die Cockpittür öffnen können. Passagiere, die zuvor Schreie gehört hätten, seien daraufhin eingedrungen und hätten den Co-Piloten überwältigt. Zwei weitere, zufällig mitreisende Flydubai-Piloten hätten anschliessend die Maschine übernommen und einen Absturz verhindert. Hentschke stützt diese Rekonstruktion unter anderem auf israelische Medienberichte und Aussagen von Passagieren gegenüber Medien.</p><div class="timeline"><article><b>Eine Möglichkeit entsteht</b><p>Die geöffnete Tür ermöglicht nach dieser Darstellung den Zugang. Dass Hilfe möglich wird, hängt an einem konkreten Handlungsschritt.</p></article><article><b>Mehrere Menschen greifen ein</b><p>Passagiere handeln gemeinsam. Die Menschen in der Kabine erscheinen als Handelnde mit eigenen Möglichkeiten.</p></article><article><b>Fachwissen wird verfügbar</b><p>Die Anwesenheit weiterer Piloten schafft eine zusätzliche Rettungsmöglichkeit. Mut allein erklärt den Ausgang ebenso wenig wie Technik allein.</p></article></div><p>Der Artikel nennt <b>174 Passagiere</b> und eine <b>Boeing 737</b>. Diese Angaben gehören zur realen Fallakte. In «Terror» geht es um einen anderen Flug und 164 Menschen an Bord. Die Zahlen dürfen im Vergleich nicht vertauscht werden.</p>${fzZeitRef('2')}<div class="callout"><b>Brücke zu Meiser:</b> Ihre Aussage wirft die Frage auf, ob Passagiere noch selbst eingreifen konnten. Eine tatsächlich gelungene Rettung zeigt, dass solche Möglichkeiten existieren können. Sie beweist keine sichere Rettung im Fall Koch.</div><a href="#lektuere/meiser">Meisers Aussage mit Text und Film untersuchen →</a></section>
<section class="section card"><span class="eyebrow">02 · SPRACHE UND ERINNERUNG</span><h2>Was der Vergleich mit dem 11. September bewirkt</h2><p>Mit «9/11» sind die Terroranschläge vom 11. September 2001 gemeint. Netanjahu beschreibt die Rettung laut Artikel als Verhinderung einer vergleichbaren Katastrophe. Damit wird der einzelne Flug in eine bereits bekannte Geschichte von Terror, massenhafter Bedrohung und Rettung eingeordnet.</p><p>Ein solcher <b>Deutungsrahmen</b> lenkt die Aufmerksamkeit: Wer erscheint als Täter, wer als Retter, wie gross wirkt die Gefahr? Der Vergleich kann verständlich machen, warum Menschen erschüttert sind. Er belegt für sich genommen weder den genauen Plan noch das Motiv des mutmasslichen Täters. Der Artikel hält selbst fest, dass viele Details unklar sind, und verweist auf Flydubais Warnung vor voreiligen Spekulationen.</p><p>Auch die Überschrift mit ihrer Aussage über «die Israelis» verlangt Prüfung. Hentschke schildert im Text unterschiedliche Reaktionen. Einzelne Stimmen und ein öffentlicher Empfang bilden keine repräsentative Befragung einer ganzen Gesellschaft.</p>${fzZeitRef('1–4')}${note('flydubai-zeit-rahmen','Flydubai · Deutungsrahmen 9/11','Welche Vorstellung erzeugt der Vergleich? Welche konkrete Tatsachenbehauptung müsste zusätzlich belegt werden? Belege mit einer ZEIT-PDF-Seite.')}${details('Vergleichshorizont','<p>Die Analogie macht eine mögliche Katastrophe emotional vorstellbar und rückt Rettende ins Zentrum. Sie ersetzt keine Untersuchung von Ablauf, Ziel und Motiv. Eine Aussage über die Wirkung der Worte ist von einer Aussage über die Absicht des Co-Piloten zu unterscheiden.</p>')}</section>
<section class="section card"><span class="eyebrow">03 · SICHERHEIT UND WAHLKAMPF</span><h2>Warum die öffentliche Darstellung politisch zählt</h2><p>Hentschke ordnet das Ereignis in den bevorstehenden israelischen Parlamentswahlkampf ein. Sie nennt den 27. Oktober als Wahltermin und berichtet, Herausforderer Gadi Eisenkot liege in Umfragen knapp vor Netanjahu. Das sind Angaben zum Zeitpunkt dieser Analyse, keine dauerhaft gültige Beschreibung.</p><p>Nach dem Artikel hatte Netanjahu kurz vor dem Vorfall vor Angriffen im Vorfeld der Wahl gewarnt. Eisenkot habe daraufhin verlangt, konkrete Gefahren in einer Sicherheitssitzung zu behandeln und Sicherheitsfragen vom Wahlkampf zu trennen. Der Empfang der geretteten Reisenden bietet Netanjahu nun eine öffentlich sichtbare Rolle an der Seite der Rettenden. Hentschke deutet dies als möglichen politischen Vorteil.</p><p><b>Politisches Kapital</b> bedeutet hier: Ein Ereignis könnte Zustimmung, Vertrauen oder Stimmen bringen. Ob es das tatsächlich tut, lässt sich aus den beschriebenen Szenen noch nicht ableiten. Ein möglicher Nutzen beweist auch keine Planung oder Verursachung des Ereignisses durch den Nutzniesser.</p><p>Die Analyse stellt Jubel am Empfang und Kritik einer anderen Reisenden gegenüber. Diese wirft Netanjahu vor, den Vorfall politisch zu nutzen, und erinnert an seine Verantwortung im Zusammenhang mit dem Hamas-Angriff vom 7. Oktober 2023. Hentschke beschreibt ausserdem, wie die neue Rettungsgeschichte eine vorherige Debatte über behauptete, nicht beachtete Warnungen vor jenem Angriff in den Hintergrund drängen könnte. Die zugrunde liegenden Vorwürfe werden im Artikel unter Verweis auf Buchrecherchen und Medienberichte wiedergegeben.</p>${fzZeitRef('3–4')}<div class="callout"><b>Kritisch auch gegenüber der Analyse:</b> Die Autorin folgert, Netanjahu habe mit seiner Warnung recht behalten. Prüfe die Reichweite: Ein späterer Vorfall belegt nicht automatisch, dass eine frühere allgemeine Warnung auf konkretem Wissen über genau diesen Vorfall beruhte.</div>${note('flydubai-zeit-politik','Flydubai · Ereignis und politischer Nutzen','Trenne: beobachteter Auftritt · zugeschriebene Aussage · mögliche Wirkung · noch fehlender Beleg. Was darf aus einem politischen Vorteil nicht gefolgert werden?')}</section>
<section class="section grid"><article class="card"><span class="eyebrow">04 · VERTRAUEN UND KONTROLLE</span><h2>Rettung schliesst Sicherheitsfragen nicht ab</h2><p>Hentschke greift die Analyse des Ha’aretz-Journalisten Amos Harel auf. Dieser fragt nach möglichen Versäumnissen bei Sicherheitsüberprüfungen und beim Mitführen einer Waffe. Zugleich beschreibt er ein Glaubwürdigkeitsproblem: Politische Warnungen können wegen mangelnden Vertrauens skeptisch aufgenommen werden.</p><p>Das sind zwei verschiedene Prüfaufträge: <b>Welche konkrete Sicherheitslücke gab es?</b> Und: <b>Warum wird einer Warnung geglaubt oder misstraut?</b> Beide verlangen Belege. Weder der erfolgreiche Ausgang noch die politische Stellung einer Person beantwortet diese Fragen allein.</p>${fzZeitRef('4')}</article><article class="card"><span class="eyebrow">05 · DIPLOMATISCHE FOLGEN</span><h2>Eine Flugroute steht auch für Beziehungen</h2><p>Der Artikel berichtet über die vorläufige Aussetzung der Tel-Aviv-Flüge durch Flydubai und Ersatzflüge von El Al. Er ordnet die seit 2021 bestehende Verbindung in die Annäherung zwischen Israel und mehreren arabischen Staaten im Rahmen der Abraham-Abkommen ein.</p><p><b>Normalisierung</b> meint hier den Aufbau regulärer diplomatischer und praktischer Beziehungen, etwa durch Reisen und Flugverbindungen. Die Unterbrechung betrifft deshalb auch ein sichtbares Zeichen dieser Annäherung. Daraus folgt noch nicht, dass diplomatische Abkommen aufgehoben werden.</p>${fzZeitRef('5')}</article></section>
<section class="section card"><h2>Zurück zu «Terror»: Was wissen wir wann?</h2><p>Vergleiche die nachträgliche Erzählung einer gelungenen Rettung mit Kochs Entscheidung unter Zeitdruck. Welche Möglichkeiten konnten Aussenstehende erkennen? Welche erfahren wir erst später? Prüfe dann, wie die Bezeichnungen «Retter», «Täter» oder «Held» dein Urteil beeinflussen, bevor die Beweise besprochen sind.</p>${note('flydubai-zeit-transfer','Flydubai · ZEIT-Analyse und Terror','Ein ZEIT-Beleg mit PDF-Seite + ein Dramenbeleg mit PDF-Seite → Gemeinsamkeit → entscheidender Unterschied → Grenze des Vergleichs')}${details('Denkhilfe · Drei voreilige Schlüsse vermeiden','<ul><li>Eine erfolgreiche Rettung zeigt eine Möglichkeit, keine Garantie für andere Situationen.</li><li>Politischer Nutzen beweist keine Urheberschaft oder vorherige Kenntnis.</li><li>Ein öffentlicher Auftritt oder eine einzelne kritische Stimme repräsentiert nicht die gesamte Bevölkerung.</li></ul>')}<p><a href="#lektuere/koch">Kochs Wissen prüfen</a> · <a href="#politik">Politik und Weltbilder</a> · <a href="#flydubai/transfer">Den ausführlichen Fallvergleich bearbeiten</a></p></section>`;}
